"use client"

import * as React from "react"
import { Check, Folder } from "lucide-react"
import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage, type AvatarColor } from "@/components/ui/avatar"
import { Badge, type BadgeColor } from "@/components/ui/badge"

/* ------------------------------------------------------------------ */
/* Timeline Event — activity entry with avatar/status rail             */
/* Figma: Timeline Event (722:58517)                                   */
/* ------------------------------------------------------------------ */

type TimelineEventProps = {
  /** Actor avatar (Type=event). */
  avatar?: { src?: string; initials?: string; color?: AvatarColor }
  /** Status dot (Type=step): tone + icon. */
  status?: { tone?: "success" | "primary" | "warning" | "muted"; icon?: React.ReactNode }
  title: React.ReactNode
  time?: React.ReactNode
  /** Small object chip under the title (Type=event) — e.g. project name. */
  object?: { icon?: React.ReactNode; label: React.ReactNode }
  /** Trailing badge/label on the title row (Type=step). */
  badge?: React.ReactNode
  badgeColor?: BadgeColor
  meta?: React.ReactNode
  /** Extra content below the title (comment excerpt, reactions, attachments …). */
  children?: React.ReactNode
  /** Draw the connector line to the next entry. */
  last?: boolean
  className?: string
}

const STATUS_TONE = {
  success: "bg-success text-success-foreground",
  primary: "bg-primary text-primary-foreground",
  warning: "bg-brand-quaternary text-foreground",
  muted: "bg-muted text-text-secondary",
}

function TimelineEvent({ avatar, status, title, time, object, badge, badgeColor = "grey", meta, children, last, className }: TimelineEventProps) {
  const lineColor = status?.tone === "success" ? "bg-success" : "bg-border"
  return (
    <div data-slot="timeline-event" className={cn("flex gap-4", className)}>
      <div className="flex w-9 shrink-0 flex-col items-center">
        {avatar ? (
          <Avatar size="lg" color={avatar.src ? undefined : avatar.color}>
            {avatar.src && <AvatarImage src={avatar.src} alt="" />}
            <AvatarFallback>{avatar.initials}</AvatarFallback>
          </Avatar>
        ) : (
          <span className={cn("grid size-8 place-items-center rounded-full [&_svg]:size-3.5", STATUS_TONE[status?.tone ?? "muted"])}>
            {status?.icon ?? <Check strokeWidth={3} />}
          </span>
        )}
        {!last && <span className={cn("mt-1 w-0.5 flex-1", lineColor)} />}
      </div>
      <div className={cn("flex min-w-0 flex-1 flex-col gap-1", !last && "pb-6")}>
        <div className="flex items-start justify-between gap-2">
          <p className="text-sm text-text-secondary [&_strong]:font-medium [&_strong]:text-foreground">{title}</p>
          {time && <span className="shrink-0 text-xs text-text-tertiary">{time}</span>}
          {badge && (
            <Badge color={badgeColor} badgeStyle="light" shape="pill" className="shrink-0">
              {badge}
            </Badge>
          )}
        </div>
        {object && (
          <span className="inline-flex w-fit items-center gap-1 rounded-md bg-muted px-2 py-0.5 text-[11px] text-text-secondary [&_svg]:size-3">
            {object.icon ?? <Folder />}
            {object.label}
          </span>
        )}
        {meta && <p className="text-xs text-text-tertiary">{meta}</p>}
        {children}
      </div>
    </div>
  )
}

export { TimelineEvent }
export type { TimelineEventProps }

import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

// Hex per color - the same hue set as the Figma "Badge" component (600 step
// of each Primitives scale). Kept as plain hex (not CSS vars) so color-mix()
// below can compute the light/opacity variants at runtime.
const BADGE_COLORS = {
  blue: "#12AFF0",
  green: "#1AD598",
  red: "#F47690",
  yellow: "#FACA4A",
  purple: "#A584F3",
  indigo: "#555CF3",
  pink: "#FE6BBA",
  orange: "#F3654A",
  alternative: "#6E6D86",
  grey: "#A2A3A3",
  black: "#000000",
  white: "#FFFFFF",
} as const

type BadgeColor = keyof typeof BADGE_COLORS

const badgeVariants = cva(
  cn(
    "group/badge inline-flex h-5 w-fit shrink-0 items-center justify-center gap-1 overflow-hidden border border-transparent px-2 text-xs font-semibold whitespace-nowrap transition duration-fast ease-entrance [&>svg]:pointer-events-none [&>svg]:size-3!",
    // Rendered as a button or link, a badge is a chip: it answers the pointer
    // and the keyboard like any other control.
    //
    // The hover cue is a ring in the label's own colour, not a brightness
    // filter. brightness() moves fill and label together, and because the label
    // polarity differs per colour — a deep hue on a bright fill in light mode,
    // white on indigo and alternative in dark mode — no single factor is safe in
    // both directions: brightness-95/125 measured 3.40:1 on dark alternative,
    // 3.81:1 on dark indigo and 4.44:1 on light orange, and the factors that
    // clear AA everywhere (98%/106%) are too small to see. A ring changes
    // nothing about the label's backdrop, so contrast is unaffected whatever the
    // colour. See /scripts/contrast-audit.mjs, which reads this hover treatment
    // out of this file.
    "[&:is(button,a)]:cursor-pointer [&:is(button,a)]:outline-none [&:is(button,a)]:hover:ring-2 [&:is(button,a)]:hover:ring-current/30 [&:is(button,a)]:active:scale-95 [&:is(button,a)]:focus-visible:ring-1 [&:is(button,a)]:focus-visible:ring-ring"
  ),
  {
    variants: {
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
    },
    defaultVariants: {
      shape: "rounded",
    },
  }
)

type BadgeStyle = "plain" | "light" | "light_border" | "border_color" | "border_grey" | "ghost"

// Hues that have a Figma tint pair (`tint/<hue>` surface + `tint-text/<hue>`
// text, both mode-aware). Grey, black and white have none and fall back to
// color-mix() below.
const TINTED: readonly BadgeColor[] = ["blue", "green", "red", "yellow", "purple", "indigo", "pink", "orange", "alternative"]

// Text on a solid fill — the Figma Badge "primary" state: white on indigo,
// alternative and black (≥ 5:1), and on every lighter hue a deep shade of that
// same hue (28 % of it), so label and icon still read as one tone and pass AA
// (4.75–7.4:1). The pale tint used before fell to 1.5–3:1. Fixed hex rather
// than mode-aware tokens on purpose: the fill keeps its bright hue in dark mode.
const WHITE_TEXT_ON: readonly BadgeColor[] = ["indigo", "alternative", "black"]

const SOLID_TEXT: Partial<Record<BadgeColor, string>> = {
  blue: "#053143",
  purple: "#2E2544",
  pink: "#471E34",
  red: "#442128",
  orange: "#441C15",
  yellow: "#463915",
  green: "#073C2B",
  grey: "#2D2E2E",
}

// The two achromatic badges are spelled out in Figma rather than derived: a
// black badge pales to the grey scale, a white one to the surface grey — a
// color-mix of #000 or #FFF lands somewhere else entirely.
// `text` sits on the badge's own fill; `ink` sits on the card or on nothing at
// all (outline, ghost), so it has to follow the mode — pure black there would
// vanish into a dark card.
const ACHROMATIC: Partial<Record<BadgeColor, { bg: string; text: string; ink: string; border: string }>> = {
  black: { bg: "var(--dark-200)", text: "#000000", ink: "var(--foreground)", border: "var(--dark-300)" },
  white: { bg: "var(--muted)", text: "var(--foreground)", ink: "var(--foreground)", border: "var(--border-control)" },
  // Grey has no tint pair; its 600 hue (#A2A3A3) is a fill colour, too pale
  // for a label on white. Text takes the tertiary text token instead (AA in
  // both modes), the surface keeps the grey hue.
  grey: {
    // 10 % (not 16 %) keeps the tertiary text at 4.7:1 on the surface — 16 % measured 4.46:1
    bg: "color-mix(in srgb, #A2A3A3 10%, var(--card))",
    text: "var(--text-tertiary)",
    ink: "var(--text-tertiary)",
    border: "color-mix(in srgb, #A2A3A3 45%, var(--card))",
  },
}

function styleToCss(color: BadgeColor, style: BadgeStyle) {
  const hex = BADGE_COLORS[color]
  const tinted = TINTED.includes(color)
  const flat = ACHROMATIC[color]
  const tintBg = flat ? flat.bg : tinted ? `var(--tint-${color})` : `color-mix(in srgb, ${hex} 12%, var(--card))`
  const tintText = flat ? flat.text : tinted ? `var(--tint-text-${color})` : hex === "#FFFFFF" ? "#000000" : hex
  const inkText = flat ? flat.ink : tintText
  const tintBorder = flat
    ? flat.border
    : tinted
      ? `color-mix(in srgb, var(--tint-text-${color}) 40%, var(--card))`
      : `color-mix(in srgb, ${hex} 40%, var(--card))`
  switch (style) {
    case "plain":
      return {
        background: hex,
        borderColor: hex,
        color: WHITE_TEXT_ON.includes(color) ? "#FFFFFF" : (SOLID_TEXT[color] ?? "#000000"),
      }
    case "light":
      return {
        background: tintBg,
        borderColor: "transparent",
        color: tintText,
      }
    case "light_border":
      return {
        background: tintBg,
        borderColor: tintBorder,
        color: tintText,
      }
    case "border_color":
      return {
        background: "var(--card)",
        borderColor: tintBorder,
        color: inkText,
      }
    case "border_grey":
      return {
        background: "var(--card)",
        borderColor: "var(--border)",
        color: inkText,
      }
    case "ghost":
      return {
        background: "transparent",
        borderColor: "transparent",
        color: inkText,
      }
  }
}

function Badge({
  className,
  shape,
  color = "blue",
  badgeStyle = "plain",
  style,
  render,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    color?: BadgeColor
    badgeStyle?: BadgeStyle
  }) {
  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(badgeVariants({ shape }), className),
        style: { ...styleToCss(color, badgeStyle), ...style },
      },
      props
    ),
    render,
    state: {
      slot: "badge",
      color,
      badgeStyle,
    },
  })
}

export { Badge, badgeVariants, BADGE_COLORS }
export type { BadgeColor, BadgeStyle }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar"
import { cn } from "@/lib/utils"

/** Tinted initials — mirrors the Figma Avatar "Style=<hue>_primary" variants
 *  (tint/<hue> background + tint-text/<hue> text, both mode-aware tokens). */
type AvatarColor =
  | "indigo"
  | "blue"
  | "purple"
  | "pink"
  | "red"
  | "orange"
  | "yellow"
  | "green"
  | "alternative"
  | "grey"

const AVATAR_COLOR_CLASSES: Record<AvatarColor, string> = {
  indigo: "bg-tint-indigo text-tint-text-indigo",
  blue: "bg-tint-blue text-tint-text-blue",
  purple: "bg-tint-purple text-tint-text-purple",
  pink: "bg-tint-pink text-tint-text-pink",
  red: "bg-tint-red text-tint-text-red",
  orange: "bg-tint-orange text-tint-text-orange",
  yellow: "bg-tint-yellow text-tint-text-yellow",
  green: "bg-tint-green text-tint-text-green",
  alternative: "bg-tint-alternative text-tint-text-alternative",
  grey: "bg-muted text-text-secondary",
}

function Avatar({
  className,
  size = "default",
  shape = "circle",
  variant = "plain",
  color,
  ...props
}: AvatarPrimitive.Root.Props & {
  /** Figma Avatar sizes: sm = 24px (2xs), xs = 28px, default = 36px (small), lg = 40px (medium), xl = 44px (large) */
  size?: "sm" | "xs" | "default" | "lg" | "xl"
  shape?: "circle" | "square"
  variant?: "plain" | "primary"
  /** Soft tint for initials avatars; ignored when an image renders. */
  color?: AvatarColor
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      data-shape={shape}
      data-variant={variant}
      data-color={color}
      className={cn(
        "group/avatar relative flex size-9 shrink-0 select-none after:absolute after:inset-0 after:border after:border-border-control after:mix-blend-darken dark:after:mix-blend-lighten",
        "data-[shape=circle]:rounded-full data-[shape=circle]:after:rounded-full",
        "data-[shape=square]:rounded-md data-[shape=square]:after:rounded-md",
        "data-[size=sm]:size-6 data-[size=xs]:size-7 data-[size=lg]:size-10 data-[size=xl]:size-11",
        // Figma keeps the glyph at 16 px and only shrinks it on the two small sizes.
        "[&_svg]:size-4 data-[size=sm]:[&_svg]:size-3 data-[size=xs]:[&_svg]:size-3.5",
        "data-[variant=primary]:bg-primary data-[variant=primary]:text-primary-foreground data-[variant=primary]:after:border-transparent",
        color && AVATAR_COLOR_CLASSES[color],
        color && "after:border-transparent",
        className
      )}
      {...props}
    />
  )
}

function AvatarImage({ className, ...props }: AvatarPrimitive.Image.Props) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      className={cn(
        "aspect-square size-full object-cover group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
        className
      )}
      {...props}
    />
  )
}

function AvatarFallback({
  className,
  ...props
}: AvatarPrimitive.Fallback.Props) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        cn(
          "flex size-full items-center justify-center bg-muted text-foreground group-data-[shape=circle]/avatar:rounded-full group-data-[shape=square]/avatar:rounded-md",
          // Initials follow the Figma type ramp: 11 / 12 / 13 / 14 / 15 px,
          // semibold everywhere except the 28 px size, which is medium.
          "text-[13px] font-semibold",
          "group-data-[size=sm]/avatar:text-[11px]",
          "group-data-[size=xs]/avatar:text-[12px] group-data-[size=xs]/avatar:font-medium",
          "group-data-[size=lg]/avatar:text-[14px] group-data-[size=xl]/avatar:text-[15px]",
          "group-data-[variant=primary]/avatar:bg-transparent group-data-[variant=primary]/avatar:text-inherit",
          "group-data-[color]/avatar:bg-transparent group-data-[color]/avatar:text-inherit"
        ),
        className
      )}
      {...props}
    />
  )
}

function AvatarBadge({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="avatar-badge"
      className={cn(
        "absolute right-0 bottom-0 z-10 inline-flex items-center justify-center rounded-full bg-primary text-primary-foreground bg-blend-color ring-[1.5px] ring-(--surface) select-none",
        // A square avatar has a real corner: the dot is centred on it, half outside, so it
        // reads as sitting on the corner. A circle has no corner and keeps the dot inside the edge.
        "group-data-[shape=square]/avatar:translate-x-1/2 group-data-[shape=square]/avatar:translate-y-1/2",
        "group-data-[size=sm]/avatar:size-2 group-data-[size=sm]/avatar:[&>svg]:hidden",
        "group-data-[size=xs]/avatar:size-2 group-data-[size=xs]/avatar:[&>svg]:hidden",
        "group-data-[size=default]/avatar:size-2 group-data-[size=default]/avatar:[&>svg]:size-2",
        "group-data-[size=lg]/avatar:size-3 group-data-[size=lg]/avatar:[&>svg]:size-2",
        "group-data-[size=xl]/avatar:size-3 group-data-[size=xl]/avatar:[&>svg]:size-2",
        className
      )}
      {...props}
    />
  )
}

function AvatarGroup({ className, children, ...props }: React.ComponentProps<"div">) {
  const rootRef = React.useRef<HTMLDivElement>(null)

  // Distance-falloff hover lift: hovering one avatar lifts it and gently
  // lifts its neighbors, then everything snaps back with an overshoot spring
  // on mouseleave. The timing-function is set inline right before the
  // --avatar-shift/--avatar-scale writes so hover-in gets a clean ease and
  // the return gets the bouncy one, without a second class for "leaving".
  function setShifts(activeIndex: number | null, phase: "in" | "out") {
    const items = rootRef.current?.querySelectorAll<HTMLElement>("[data-avatar-hover-item]")
    if (!items) return
    const timing = phase === "out" ? "var(--ease-overshoot)" : "cubic-bezier(0.22, 1, 0.36, 1)"
    items.forEach((el, index) => {
      el.style.transitionTimingFunction = timing
      if (activeIndex == null) {
        el.style.setProperty("--avatar-shift", "0px")
        el.style.setProperty("--avatar-scale-active", "1")
        return
      }
      const distance = Math.abs(index - activeIndex)
      el.style.setProperty("--avatar-shift", `${(-4 * 0.45 ** distance).toFixed(3)}px`)
      el.style.setProperty("--avatar-scale-active", index === activeIndex ? "1.05" : "1")
    })
  }

  return (
    <div
      ref={rootRef}
      data-slot="avatar-group"
      onMouseLeave={() => setShifts(null, "out")}
      className={cn(
        "group/avatar-group flex -space-x-3 [&_[data-slot=avatar]]:ring-2 [&_[data-slot=avatar]]:ring-(--surface)",
        className
      )}
      {...props}
    >
      {React.Children.map(children, (child, index) => (
        <div
          data-avatar-hover-item
          onMouseEnter={() => setShifts(index, "in")}
          className="origin-center transition-transform ease-entrance duration-slow will-change-transform [transform:translateY(var(--avatar-shift,0px))_scale(var(--avatar-scale-active,1))] motion-reduce:[transform:none] motion-reduce:transition-none"
        >
          {child}
        </div>
      ))}
    </div>
  )
}

function AvatarGroupCount({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="avatar-group-count"
      className={cn(
        "relative flex size-9 shrink-0 items-center justify-center rounded-full bg-muted text-[12px] font-semibold text-text-secondary ring-2 ring-(--surface) group-has-data-[size=lg]/avatar-group:size-10 group-has-data-[size=xl]/avatar-group:size-11 group-has-data-[size=xs]/avatar-group:size-7 group-has-data-[size=sm]/avatar-group:size-6 [&>svg]:size-4 group-has-data-[size=lg]/avatar-group:[&>svg]:size-5 group-has-data-[size=sm]/avatar-group:[&>svg]:size-3",
        className
      )}
      {...props}
    />
  )
}

export type { AvatarColor }
export {
  Avatar,
  AvatarImage,
  AvatarFallback,
  AvatarGroup,
  AvatarGroupCount,
  AvatarBadge,
}

import type { ReactNode } from "react"
import { cn } from "@/lib/utils"
import { readableOn, readableOnCss } from "@/lib/readable-on"

type TimelineItem = {
  id: string
  title: ReactNode
  description?: ReactNode
  timestamp?: string
  icon?: ReactNode
  /** A person instead of the dot, for activity feeds: an Avatar, for example. */
  avatar?: ReactNode
  /** Fill of the dot. The glyph inside switches between white and a dark colour so it stays readable (WCAG 1.4.11). */
  color?: string
}

/** Dot fill plus a glyph colour with enough contrast on it. */
function dotStyle(color: string | undefined) {
  const tone = color ? readableOn(color) : "light"
  return {
    className: tone === "dark" ? "text-neutral-dark-content" : "text-white",
    // A fill that is not a literal colour (var(), color-mix) is resolved in CSS.
    style: {
      backgroundColor: color ?? "var(--primary)",
      ...(tone === null && color ? { color: readableOnCss(color) } : null),
    },
  }
}

function Timeline({
  items,
  orientation = "vertical",
  compact = false,
  className,
}: {
  items: TimelineItem[]
  /** "vertical" stacks the entries, "horizontal" lays them out in a row with the time above each dot. */
  orientation?: "vertical" | "horizontal"
  /** Smaller dots and text, for milestones and long lists. */
  compact?: boolean
  className?: string
}) {
  const dot = (item: TimelineItem) =>
    item.avatar ?? (
      <span
        data-slot="timeline-dot"
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full",
          compact ? "size-4 [&_svg]:size-2.5" : "size-6",
          dotStyle(item.color).className
        )}
        style={dotStyle(item.color).style}
      >
        {item.icon ?? <span className={cn("rounded-full bg-current", compact ? "size-1" : "size-1.5")} />}
      </span>
    )

  if (orientation === "horizontal") {
    return (
      <div data-slot="timeline" data-orientation="horizontal" className={cn("flex", className)}>
        {items.map((item, i) => (
          <div key={item.id} className="flex min-w-0 flex-1 flex-col gap-2">
            {item.timestamp && <span className="text-xs text-text-tertiary">{item.timestamp}</span>}
            <div className="flex items-center">
              {dot(item)}
              {i !== items.length - 1 && <span className="mx-2 h-px flex-1 bg-border" />}
            </div>
            <div className="flex flex-col gap-0.5 pr-3">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.description && <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>}
            </div>
          </div>
        ))}
      </div>
    )
  }

  return (
    <div data-slot="timeline" className={cn("flex flex-col", className)}>
      {items.map((item, i) => (
        <div key={item.id} className="flex gap-3">
          <div className="flex flex-col items-center">
            {dot(item)}
            {i !== items.length - 1 && <span className="my-1 w-px flex-1 bg-border" />}
          </div>
          <div className={cn("flex flex-col gap-0.5", i !== items.length - 1 && (compact ? "pb-4" : "pb-6"))}>
            <div className="flex items-center gap-2">
              <p className={cn("font-semibold text-foreground", compact ? "text-xs" : "text-sm")}>{item.title}</p>
              {item.timestamp && (
                <span className="text-xs text-text-tertiary">{item.timestamp}</span>
              )}
            </div>
            {item.description && (
              <p className={cn("text-text-secondary", compact ? "text-xs" : "text-[13px]")}>{item.description}</p>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

